import manifest from "./imageManifest.json";

/** Every key is generated by `npm run assets` straight from the PDF. */
export type ImageKey = keyof typeof manifest;

const base = import.meta.env.BASE_URL.replace(/\/$/, "");

export const imageMeta = (key: ImageKey) => manifest[key];

export const imageSrc = (key: ImageKey, width?: number) => {
  const { widths } = manifest[key];
  const chosen = width ? (widths.find((w) => w >= width) ?? widths[widths.length - 1]) : widths[widths.length - 1];
  return `${base}/images/${key}-${chosen}.webp`;
};

export const imageSrcSet = (key: ImageKey) =>
  manifest[key].widths.map((w) => `${base}/images/${key}-${w}.webp ${w}w`).join(", ");

export const imageRatio = (key: ImageKey) => manifest[key].w / manifest[key].h;

